const aspectRatios={'16:9':[16,9],'9:16':[9,16],'1:1':[1,1],'4:3':[4,3],'21:9':[21,9]};
function outputSize(ratio,short){const [x,y]=aspectRatios[ratio];return x>=y?[2*Math.round(short*x/y/2),short]:[short,2*Math.round(short*y/x/2)]}
let currentPreviewRatio='16:9';
