async function showExportCheck(){closeMenus();if(!project||busy||saving)return;stop();const version=++exportCheckVersion,revision=editRevision,source=projectPath;
 $('exportCheckSummary').textContent='원본 파일을 확인하는 중…';$('exportCheckList').replaceChildren();$('exportCheckStart').disabled=true;$('exportCheckDialog').showModal();
 const clips=all(null,false),sources=new Map();for(const {track,clip} of clips)if(track.kind!=='subtitle'&&clip.path)sources.set(track.kind+'|'+clip.path,{kind:track.kind,path:clip.path});
 const checks=await Promise.all([...sources.values()].map(async item=>{try{return {...item,meta:await media(item.path,item.kind)}}catch(error){return {...item,error:error.message||String(error)}}}));
 if(version!==exportCheckVersion||!$('exportCheckDialog').open||revision!==editRevision||source!==projectPath)return;
 let errors=0,warnings=0;for(const item of checks)if(item.error){exportCheckLine('원본을 열 수 없음: '+item.path+' ('+item.error+')','error');errors++}
 for(const {track,clip} of clips){if(track.kind==='subtitle'||!clip.path)continue;const result=checks.find(item=>item.kind===track.kind&&item.path===clip.path);if(result?.meta&&!clip.loop&&!clip.padEnd&&clip.sourceIn+clip.duration>result.meta.duration+.02){exportCheckLine('원본 길이 부족: '+clip.title,'error');errors++}}
 if(!clips.some(({track})=>track.kind==='video'&&track.enabled!==false)){exportCheckLine('활성 영상 클립이 없어 검은 화면으로 출력됩니다.','warning');warnings++}
 if(!project.export.subtitles&&clips.some(({track})=>track.kind==='subtitle'&&track.enabled!==false)){exportCheckLine('자막 출력이 꺼져 있어 자막 클립이 MP4에 표시되지 않습니다.','warning');warnings++}
 const pending=(project.markers||[]).filter(item=>!item.done);if(pending.length){exportCheckLine('완료하지 않은 촬영 메모 '+pending.length+'개: '+pending.slice(0,3).map(item=>item.title).join(', '),'warning');warnings++}
 if(modified){exportCheckLine('저장되지 않은 변경이 있습니다. MP4 옆에 현재 편집 내용의 프로젝트 사본이 저장됩니다.','warning');warnings++}
 if(!errors)exportCheckLine('원본 '+sources.size+'개 확인 완료 · '+clips.length+'개 클립','ok');
 $('exportCheckSummary').textContent=`${$('outputDimensions').textContent} · ${project.export.fps}fps · ${stamp(total())} · 오류 ${errors}개 · 확인 사항 ${warnings}개`;
 exportCheckRevision=revision;$('exportCheckStart').disabled=errors>0;
}
