function addAsset(meta,select=true){project.assets??=[];const kind=meta.kind||'video';let asset=project.assets.find(a=>a.path===meta.path&&a.kind===kind);if(asset){if(Number.isFinite(meta.duration))asset.duration=meta.duration}else{remember();asset={id:uid(),kind,name:meta.name||meta.path.split(/[\\/]/).pop(),path:meta.path,duration:meta.duration,defaultVolume:1,...(kind==='audio'?{role:'narration',loop:false}:{})};project.assets.push(asset);modified=true;editRevision++;renderAssets()}if(select)selectAsset(asset);return asset}
function assetSetting(asset,key,value){remember();asset[key]=value;modified=true;editRevision++;renderAssets();renderInspector()}
function renderAssetInspector(box,asset){$('inspectorTitle').textContent='에셋 정보';const type=document.createElement('p');type.className='badge';type.textContent=kindName[asset.kind]+' 원본';box.append(type);field(box,'표시 이름',asset.name,v=>assetSetting(asset,'name',v.trim()||asset.name),{type:'text'});const path=document.createElement('p');path.className='hint asset-path';path.textContent='파일: '+asset.path;box.append(path);const length=document.createElement('p');length.className='hint';length.textContent='원본 길이: '+(Number.isFinite(asset.duration)?stamp(asset.duration):'확인 중…');box.append(length);field(box,'새 클립 기본 음량',asset.defaultVolume??1,v=>assetSetting(asset,'defaultVolume',v),{min:0,max:2,step:'.05'});if(asset.kind==='audio'){const label=document.createElement('label');label.textContent='새 클립 음원 종류';const role=document.createElement('select');for(const [value,name] of [['narration','나레이션'],['music','배경음악'],['effect','효과음']]){const option=document.createElement('option');option.value=value;option.textContent=name;role.append(option)}role.value=asset.role||'narration';role.onchange=()=>assetSetting(asset,'role',role.value);label.append(role);box.append(label);const loopLabel=document.createElement('label');const loop=document.createElement('input');loop.type='checkbox';loop.checked=!!asset.loop;loop.onchange=()=>assetSetting(asset,'loop',loop.checked);loopLabel.append(loop,' 새 클립 구간 반복');box.append(loopLabel)}const preview=document.createElement('div');preview.className='asset-preview';const player=document.createElement(asset.kind==='audio'?'audio':'video');assetPreviewPlayer=player;player.controls=true;player.preload='metadata';if(asset.kind==='video'){player.muted=true;player.playsInline=true}preview.append(player);box.append(preview);media(asset.path,asset.kind).then(meta=>{if(selectedAsset!==asset.id||!player.isConnected)return;player.src=meta.url;if(asset.duration!==meta.duration){asset.duration=meta.duration;length.textContent='원본 길이: '+stamp(meta.duration);const card=document.querySelector(`.asset-card[data-id="${asset.id}"] small`);if(card)card.textContent=kindName[asset.kind]+' · '+stamp(meta.duration)}}).catch(e=>{if(selectedAsset===asset.id)length.textContent='원본 확인 실패: '+e.message});const action=button('재생 위치에 전체 길이로 배치',()=>assetClip(asset));action.className='primary';box.append(action)}
function renderRelinkControls(box,asset){
 const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='원본 파일 다시 연결';details.append(summary);
 const input=document.createElement('input');input.value=asset.path;input.setAttribute('aria-label','새 원본 파일 경로');details.append(input);
 if(window.EDITOR_DESKTOP){const browse=button('Windows 파일 선택',async()=>{try{const path=await window.pywebview.api.choose_media(asset.kind);if(path)input.value=path}catch(e){fail(e)}});details.append(browse)}
 details.append(button('선택한 원본으로 연결',async()=>{try{const old=asset.path,meta=await media(input.value,asset.kind);for(const {track,clip} of all(null,false))if(track.kind===asset.kind&&clip.path===old&&(!clip.loop&&!clip.padEnd&&clip.sourceIn+clip.duration>meta.duration+.02||clip.sourceIn>=meta.duration))throw Error('새 원본이 기존 클립의 사용 구간보다 짧습니다.');mutate(()=>{asset.path=meta.path;asset.duration=meta.duration;for(const {track,clip} of all(null,false))if(track.kind===asset.kind&&clip.path===old)clip.path=meta.path});renderAssets();message('원본 파일을 다시 연결했습니다.')}catch(e){fail(e)}}));
 box.append(details);
}
function selectAsset(asset){selectedAsset=asset.id;selectedClip=null;document.querySelectorAll('.asset-card').forEach(e=>e.classList.toggle('selected',e.dataset.id===asset.id));document.querySelectorAll('.clip').forEach(e=>e.classList.remove('selected'));updateEditControls();renderInspector()}
function dragAsset(card,asset,e){if(busy)return;const x=e.clientX,y=e.clientY;let ghost=null,target=null;const clear=()=>{ghost?.remove();document.querySelectorAll('.track-lane.asset-over').forEach(l=>l.classList.remove('asset-over'))};pointerDrag(card,e,ev=>{if(!ghost&&Math.hypot(ev.clientX-x,ev.clientY-y)<6)return;if(!ghost){ghost=document.createElement('div');ghost.className='asset-drag-ghost';ghost.textContent=asset.name;document.body.append(ghost)}ghost.style.left=ev.clientX+14+'px';ghost.style.top=ev.clientY+12+'px';const lane=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('.track-lane');const row=lane?.closest('.track-row');target=project.tracks.find(t=>t.id===row?.dataset.track&&t.kind===asset.kind)?lane:null;document.querySelectorAll('.track-lane.asset-over').forEach(l=>l.classList.remove('asset-over'));target?.classList.add('asset-over');ghost.classList.toggle('invalid',!!lane&&!target)},ev=>{const lane=target;clear();if(!ghost){selectAsset(asset);return}if(!lane){message(`${kindName[asset.kind]} 트랙에 놓으세요.`);return}const track=project.tracks.find(t=>t.id===lane.closest('.track-row').dataset.track);placeAsset(asset,track,snapped((ev.clientX-lane.getBoundingClientRect().left)/scale))},clear)}
function renderAssets(){++assetRender;const box=$('assetList');box.replaceChildren();const assets=project.assets||[];if(!assets.some(a=>a.id===selectedAsset))selectedAsset=null;if(!assets.length){box.textContent='아직 불러온 에셋이 없습니다.';return}const query=$('assetSearch').value.trim().toLocaleLowerCase();const filtered=query?assets.filter(asset=>asset.name.toLocaleLowerCase().includes(query)||asset.path.toLocaleLowerCase().includes(query)):assets;if(!filtered.length){box.textContent='검색 결과가 없습니다.';return}for(const asset of filtered){const card=button('',()=>selectAsset(asset));card.className='asset-card '+asset.kind+(selectedAsset===asset.id?' selected':'');card.dataset.id=asset.id;card.title=asset.path;card.onpointerdown=e=>dragAsset(card,asset,e);const icon=document.createElement('span');icon.className='asset-icon';icon.textContent=asset.kind==='audio'?'♪':'▶';const copy=document.createElement('span');copy.className='asset-copy';copy.textContent=asset.name;const detail=document.createElement('small');detail.textContent=kindName[asset.kind]+' · '+(Number.isFinite(asset.duration)?stamp(asset.duration):'길이 확인 전');copy.append(detail);card.append(icon,copy);box.append(card)}}
$('assetSearch').oninput=renderAssets;
function sidebarTab(name){for(const [tab,pane] of [['mediaTab','mediaPane'],['devlogTab','devlogPane']]){$(tab).setAttribute('aria-selected',String(tab===name));$(pane).hidden=tab!==name}}
$('mediaTab').onclick=()=>sidebarTab('mediaTab');$('devlogTab').onclick=()=>sidebarTab('devlogTab');
for(const [id,action] of [['devlogNarrationShortcut','narration'],['devlogScriptShortcut','script'],['devlogSequenceShortcut','sequence'],['devlogAllShortcut',null]])$(id).onclick=()=>window.EditorPlugins.open('devlog',action).catch(fail);
const compareShortcut=button('이전/현재 비교 장면',()=>window.EditorPlugins.open('devlog','comparison').catch(fail));compareShortcut.id='devlogCompareShortcut';$('devlogAllShortcut').before(compareShortcut);
function renderMarkers(){const list=$('markerList');list.replaceChildren();const markers=[...(project.markers||[])].sort((a,b)=>a.time-b.time);$('markerCount').textContent=`${markers.filter(item=>item.done).length}/${markers.length} 완료`;if(!markers.length){list.textContent='현재 촬영 메모가 없습니다.';return}for(const marker of markers){const row=document.createElement('div');row.className='marker-row';const done=document.createElement('input');done.type='checkbox';done.checked=!!marker.done;done.setAttribute('aria-label',marker.title+' 완료');done.onchange=()=>mutate(()=>marker.done=done.checked);const jump=button(stamp(marker.time)+' · '+marker.title,()=>seek(marker.time));jump.className='marker-jump'+(marker.done?' done':'');const remove=button('×',()=>mutate(()=>project.markers=project.markers.filter(item=>item.id!==marker.id)));remove.title='촬영 메모 삭제';row.append(done,jump,remove);list.append(row)}}
$('markerAdd').onclick=()=>{const title=$('markerTitle').value.trim();if(!title){message('촬영 메모를 입력하세요.');return}if((project.markers||[]).length>=200){message('촬영 메모는 최대 200개입니다.');return}mutate(()=>{project.markers??=[];project.markers.push({id:uid(),title,time:position,done:false})});$('markerTitle').value='';message('현재 위치에 촬영 메모를 추가했습니다.')};
$('markerTitle').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('markerAdd').click()}};
async function placeAsset(asset,track,start){if(busy||!asset||!track)return;if(asset.kind!==track.kind){message(`${kindName[asset.kind]} 에셋은 ${kindName[asset.kind]} 트랙에 놓으세요.`);return}try{let duration=asset.duration;if(!Number.isFinite(duration)||duration<=0){duration=(await media(asset.path,asset.kind)).duration;asset.duration=duration;renderAssets()}if(!Number.isFinite(duration)||duration<.04)throw Error('원본 길이를 확인할 수 없습니다.');start=Math.max(0,start);const clip={id:uid(),title:asset.name,start,duration,sourceIn:0,path:asset.path,volume:asset.defaultVolume??1,padEnd:false,...(asset.kind==='audio'?{role:asset.role||'narration',loop:!!asset.loop}:{})};if(start+duration>3600)throw Error('1시간 범위 안에 에셋을 배치하세요.');if(!validPlacement(track,clip))throw Error('같은 영상 트랙의 기존 클립과 겹칩니다.');selectedAsset=null;selectedTrack=track.id;selectedClip=clip.id;mutate(()=>track.clips.push(clip));renderAssets();seek(start);message(`${kindName[asset.kind]} 클립 배치 완료 · ${stamp(duration)}`)}catch(e){fail(e)}}
function assetClip(asset){asset??=project.assets.find(a=>a.id===selectedAsset);if(!asset)return;let track=selection().track;if(track?.kind!==asset.kind)track=project.tracks.find(t=>t.kind===asset.kind);if(!track){track={id:uid(),name:kindName[asset.kind]+' 1',kind:asset.kind,enabled:true,clips:[]};mutate(()=>project.tracks.unshift(track))}placeAsset(asset,track,snapped(position))}
function uploadMedia(file,kind,progress){return new Promise((resolve,reject)=>{const request=new XMLHttpRequest();request.open('POST','/api/upload');request.setRequestHeader('X-Editor-Token',token);request.setRequestHeader('X-File-Name',encodeURIComponent(file.name));request.setRequestHeader('X-Media-Kind',kind);request.setRequestHeader('Content-Type','application/octet-stream');request.upload.onprogress=e=>{if(e.lengthComputable)progress(Math.round(e.loaded/e.total*100))};request.onload=()=>{try{const data=JSON.parse(request.responseText);if(request.status>=400)throw Error(data.error||'파일 불러오기 실패');resolve(data)}catch(e){reject(e)}};request.onerror=()=>reject(Error('로컬 편집기에 연결할 수 없습니다. 서버 실행 상태를 확인하세요.'));request.send(file)})}
$('importAssets').onclick=()=>{$('assetFiles').value='';$('assetFiles').click()};
function fileKind(file){const extension=file.name.split('.').pop().toLowerCase();if(file.type.startsWith('video/')||['mp4','mov','mkv','webm','m4v'].includes(extension))return'video';if(file.type.startsWith('audio/')||['wav','mp3','ogg','flac','m4a'].includes(extension))return'audio';throw Error('지원하지 않는 에셋 형식입니다: '+file.name)}
$('assetFiles').onchange=async()=>{const files=[...$('assetFiles').files];if(!files.length)return;stop();busy=true;lock(true);$('cancelJob').hidden=true;$('progress').hidden=true;let count=0;try{for(const file of files){const kind=fileKind(file);const meta=await uploadMedia(file,kind,p=>message(file.name+' · 불러오는 중 '+p+'%'));addAsset(meta);count++}message(count+'개 에셋 불러오기 완료')}catch(e){fail(e)}finally{busy=false;lock(false)}};
$('importPath').onclick=async()=>{try{const kind=$('assetPathKind').value;const meta=await media($('assetPath').value,kind);addAsset(meta);message(`${kindName[kind]} 에셋 연결 완료`)}catch(e){fail(e)}};
let pendingAspect='16:9',aspectCommitted=false;
$('aspectOpen').onclick=()=>{closeMenus();if(!project||busy)return;pendingAspect=project.export.aspectRatio||'16:9';aspectCommitted=false;previewAspect(pendingAspect);$('aspectDialog').showModal()};
for(const option of document.querySelectorAll('.aspect-option'))option.onclick=()=>{pendingAspect=option.dataset.ratio;previewAspect(pendingAspect)};
$('aspectCancel').onclick=()=>$('aspectDialog').close();
$('aspectApply').onclick=()=>{if(!project)return;if(pendingAspect!==(project.export.aspectRatio||'16:9'))mutate(()=>project.export.aspectRatio=pendingAspect);aspectCommitted=true;$('aspectDialog').close()};
$('aspectDialog').addEventListener('close',()=>{if(!aspectCommitted&&project)previewAspect(project.export.aspectRatio||'16:9')});
fetch('/api/state').then(r=>r.json()).then(data=>{defaultProjectFolder=data.projectPath?.replace(/[\\/][^\\/]+$/,'')||''}).catch(fail);requestAnimationFrame(tick);
